//! Pure original operand correspondence. No database, source/actor authority or release.
use std::io::{Read,Write};use serde_json::json;use weft_core::error::{Diagnostic,Result};
fn fail()->Diagnostic{Diagnostic::new("WFT-SECURITY-OPERAND-INPUT","input","Bounded original operand input required")}
fn run()->Result<String>{let mut bytes=Vec::new();std::io::stdin().take(16_000_001).read_to_end(&mut bytes).map_err(|_|fail())?;if bytes.len()>16_000_000{return Err(fail());}let v=weft_core::json::checked_json(std::str::from_utf8(&bytes).map_err(|_|fail())?).map_err(|_|fail())?;let o=v.as_object().ok_or_else(fail)?;if o.len()!=2||!o.contains_key("requestJson")||!o.contains_key("batchJson"){return Err(fail());}let request=v["requestJson"].as_str().ok_or_else(fail)?;let batch=v["batchJson"].as_str().ok_or_else(fail)?;
 weft_core::security_mapping_transport::with_security_mapping_context(request,|ctx|{let checked=weft_core::security_operand_values::check_operand_values(ctx,batch)?;Ok(json!({"version":"weft.security.operand-values.inspected/0.1-candidate","securityReady":false,"contextSha256":checked.context_sha256(),"batchSha256":checked.batch_sha256(),"counts":checked.counts()}).to_string()+"\n")})}
fn main(){match run(){Ok(out)=>{if std::io::stdout().write_all(out.as_bytes()).is_err(){std::process::exit(1)}},Err(d)=>{let _=writeln!(std::io::stderr(),"{}",serde_json::to_string(&d).unwrap());std::process::exit(1)}}}
